+ (UIImage *)imageFromBase64:(NSString *)b64 size:(CGFloat)sz {
    NSData *data = [[NSData alloc] initWithBase64EncodedString:b64 options:0];
    UIImage *img = [UIImage imageWithData:data];
    if (!img) return nil;
    UIGraphicsBeginImageContextWithOptions(CGSizeMake(sz, sz), NO, 0);
    [img drawInRect:CGRectMake(0, 0, sz, sz)];
    UIImage *result = UIGraphicsGetImageFromCurrentImageContext();
    UIGraphicsEndImageContext();
    return [result imageWithRenderingMode:UIImageRenderingModeAlwaysOriginal];
}

#define kAWECACardTag 19541
#define kAWECASoftTag 19542
#define kAWECAInvertBtnTag 19543

// 跟随抖音主题
static BOOL AWECADouyinIsLight(void) {
    Class cls = NSClassFromString(@"AWEUIThemeManager");
    if (cls && [cls respondsToSelector:@selector(isLightTheme)]) {
        return ((BOOL (*)(id, SEL))objc_msgSend)(cls, @selector(isLightTheme));
    }
    return [UITraitCollection currentTraitCollection].userInterfaceStyle != UIUserInterfaceStyleDark;
}

static UIColor *AWECAPageBG(void) {
    if (AWECADouyinIsLight())
        return [UIColor colorWithRed:0.949 green:0.949 blue:0.957 alpha:1];
    return [UIColor colorWithRed:0.067 green:0.067 blue:0.078 alpha:1];
}
static UIColor *AWECACardBG(void) {
    if (AWECADouyinIsLight()) return [UIColor whiteColor];
    return [UIColor colorWithRed:0.102 green:0.102 blue:0.125 alpha:1];
}
static UIColor *AWECASoftFill(void) {
    if (AWECADouyinIsLight())
        return [UIColor colorWithRed:0.953 green:0.953 blue:0.961 alpha:1];
    return [UIColor colorWithRed:0.063 green:0.063 blue:0.078 alpha:1];
}
static UIColor *AWECALabel(void) {
    return AWECADouyinIsLight() ? [UIColor colorWithWhite:0.12 alpha:1] : [UIColor colorWithWhite:0.96 alpha:1];
}
static UIColor *AWECATertiary(void) {
    return AWECADouyinIsLight() ? [UIColor colorWithWhite:0.55 alpha:1] : [UIColor colorWithWhite:0.58 alpha:1];
}
static UIColor *AWECAOnPrimary(void) {
    return AWECADouyinIsLight() ? [UIColor whiteColor] : [UIColor colorWithWhite:0.12 alpha:1];
}

