#pragma mark - 弹面板

- (void)showPickerFromViewController:(UIViewController *)vc {
    if (!vc) vc = [AWECAUtils topViewController];
    if (!vc) return;
    AWECAAudioPickerController *picker = [AWECAAudioPickerController shared];
    UINavigationController *nav = [[UINavigationController alloc] initWithRootViewController:picker];
    nav.modalPresentationStyle = UIModalPresentationPageSheet;
    nav.overrideUserInterfaceStyle = AWECADouyinIsLight() ? UIUserInterfaceStyleLight : UIUserInterfaceStyleDark;
    if (@available(iOS 15.0, *)) {
        UISheetPresentationController *sheet = nav.sheetPresentationController;
        if (sheet) {
            sheet.detents = @[UISheetPresentationControllerDetent.mediumDetent,
                              UISheetPresentationControllerDetent.largeDetent];
            sheet.prefersGrabberVisible = YES;
        }
    }
    [vc presentViewController:nav animated:YES completion:nil];
}

- (void)viewDidLoad {
    [super viewDidLoad];
    self.view.backgroundColor = AWECAPageBG();
    [self aweca_buildUI];
    [self aweca_listenDouyinTheme];
    [self aweca_syncInterfaceStyle];
    [self aweca_applyTheme];
}

- (void)dealloc {
    [[NSNotificationCenter defaultCenter] removeObserver:self];
}

- (void)aweca_listenDouyinTheme {
    NSNotificationCenter *nc = [NSNotificationCenter defaultCenter];
    [nc addObserver:self selector:@selector(aweca_themeMaybeChanged:) name:UIApplicationDidBecomeActiveNotification object:nil];
    NSArray *names = @[
        @"AWEUIThemeDidChangeNotification",
        @"AWEThemeDidChangeNotification",
        @"AWEUICurrentThemeDidChangeNotification",
        @"AWEDarkModeDidChangeNotification",
        @"AWEInterfaceThemeDidChangeNotification",
        @"AWEUIColorThemeDidChangeNotification",
    ];
    for (NSString *n in names)
        [nc addObserver:self selector:@selector(aweca_themeMaybeChanged:) name:n object:nil];
    Class cls = NSClassFromString(@"AWEUIThemeManager");
    if (cls && [cls respondsToSelector:@selector(sharedInstance)]) {
        id mgr = ((id (*)(id, SEL))objc_msgSend)(cls, @selector(sharedInstance));
        if (mgr)
            [nc addObserver:self selector:@selector(aweca_themeMaybeChanged:) name:nil object:mgr];
    }
}

- (void)aweca_themeMaybeChanged:(NSNotification *)note {
    (void)note;
    [self aweca_syncInterfaceStyle];
    [self aweca_applyTheme];
}

- (void)viewWillAppear:(BOOL)animated {
    [super viewWillAppear:animated];
    BOOL isRoot = (self.navigationController.viewControllers.firstObject == self);
    if (self.navigationController) {
        [self.navigationController setNavigationBarHidden:isRoot animated:animated];
        self.navigationItem.rightBarButtonItem = nil;
    }
    self.headerTitleLabel.hidden = !isRoot;
    [self aweca_syncInterfaceStyle];
    [self aweca_applyTheme];
    [self aweca_refreshUI];
}

- (void)traitCollectionDidChange:(UITraitCollection *)previousTraitCollection {
    [super traitCollectionDidChange:previousTraitCollection];
    [self aweca_syncInterfaceStyle];
    [self aweca_applyTheme];
}

- (void)viewDidLayoutSubviews {
    [super viewDidLayoutSubviews];
    NSInteger light = AWECADouyinIsLight() ? 1 : 0;
    if (light != self.awecaLastLight) {
        self.awecaLastLight = light;
        [self aweca_syncInterfaceStyle];
        [self aweca_applyTheme];
    }
}

- (void)aweca_syncInterfaceStyle {
    UIUserInterfaceStyle s = AWECADouyinIsLight() ? UIUserInterfaceStyleLight : UIUserInterfaceStyleDark;
    if (self.overrideUserInterfaceStyle != s)
        self.overrideUserInterfaceStyle = s;
    if (self.navigationController && self.navigationController.overrideUserInterfaceStyle != s)
        self.navigationController.overrideUserInterfaceStyle = s;
}

- (void)aweca_applyTheme {
    UIColor *label = AWECALabel();
    UIColor *onP = AWECAOnPrimary();
    BOOL light = AWECADouyinIsLight();
    self.view.backgroundColor = AWECAPageBG();
    self.headerTitleLabel.textColor = label;
    [self aweca_recolorTree:self.view];
    self.toneField.backgroundColor = AWECASoftFill();
    self.toneField.textColor = label;
    self.toneField.keyboardAppearance = light ? UIKeyboardAppearanceLight : UIKeyboardAppearanceDark;
    self.speedSlider.minimumTrackTintColor = label;
    self.volSlider.minimumTrackTintColor = label;
    self.pitchSlider.minimumTrackTintColor = label;
    self.silSlider.minimumTrackTintColor = label;
    self.composeBtn.backgroundColor = label;
    [self.composeBtn setTitleColor:onP forState:UIControlStateNormal];
    self.previewBtn.backgroundColor = label;
    [self.previewBtn setTitleColor:onP forState:UIControlStateNormal];
    self.voiceNameLabel.textColor = label;
    self.localTitle.textColor = label;
    self.localSub.textColor = AWECATertiary();
    self.speedVal.textColor = AWECATertiary();
    self.volVal.textColor = AWECATertiary();
    self.pitchVal.textColor = AWECATertiary();
    self.silVal.textColor = AWECATertiary();
    self.favTable.backgroundColor = AWECACardBG();
    self.favTable.separatorColor = AWECASoftFill();
    if (@available(iOS 15.0, *)) {
        for (UIButton *b in self.locActBtns) {
            if (!b.configuration) continue;
            UIButtonConfiguration *cfg = b.configuration;
            cfg.baseForegroundColor = label;
            cfg.background.backgroundColor = AWECASoftFill();
            b.configuration = cfg;
        }
    }
    UINavigationBar *bar = self.navigationController.navigationBar;
    if (bar) {
        UINavigationBarAppearance *ap = [[UINavigationBarAppearance alloc] init];
        [ap configureWithOpaqueBackground];
        ap.backgroundColor = AWECAPageBG();
        ap.titleTextAttributes = @{NSForegroundColorAttributeName: label};
        bar.standardAppearance = ap;
        bar.scrollEdgeAppearance = ap;
        bar.compactAppearance = ap;
        bar.tintColor = label;
    }
    [self aweca_paintDialect];
    [self.favTable reloadData];
}

- (void)aweca_recolorTree:(UIView *)v {
    if (v.tag == kAWECACardTag) v.backgroundColor = AWECACardBG();
    else if (v.tag == kAWECASoftTag) v.backgroundColor = AWECASoftFill();
    else if (v.tag == kAWECAInvertBtnTag) {
        v.backgroundColor = AWECALabel();
        if ([v isKindOfClass:[UIButton class]])
            [(UIButton *)v setTitleColor:AWECAOnPrimary() forState:UIControlStateNormal];
    }
    for (UIView *s in v.subviews) [self aweca_recolorTree:s];
}

- (void)aweca_finishAndClose {
    if (self.embeddedInCommentTab) {
        [self aweca_refreshUI];
        return;
    }
    [self dismissViewControllerAnimated:YES completion:nil];
}

- (void)aweca_dismissKB {
    [self.view endEditing:YES];
}

- (void)aweca_showNavForPush {
    self.headerTitleLabel.hidden = YES;
    if (self.navigationController) {
        [self.navigationController setNavigationBarHidden:NO animated:YES];
    }
}

