- (void)aweca_buildUI {
    const CGFloat titlePad = 12.0;
    UILabel *titleLab = [[UILabel alloc] init];
    titleLab.text = @"Developed by CookieOdd";
    titleLab.font = [UIFont systemFontOfSize:15 weight:UIFontWeightSemibold];
    titleLab.textColor = [UIColor labelColor];
    titleLab.textAlignment = NSTextAlignmentCenter;
    titleLab.adjustsFontSizeToFitWidth = YES;
    titleLab.minimumScaleFactor = 0.7;
    titleLab.translatesAutoresizingMaskIntoConstraints = NO;
    self.headerTitleLabel = titleLab;
    [self.view addSubview:titleLab];

    UISegmentedControl *seg = [[UISegmentedControl alloc] initWithItems:@[@"合成", @"本地"]];
    seg.selectedSegmentIndex = 0;
    seg.translatesAutoresizingMaskIntoConstraints = NO;
    [seg addTarget:self action:@selector(aweca_tabChanged:) forControlEvents:UIControlEventValueChanged];
    self.segment = seg;
    [self.view addSubview:seg];

    UIScrollView *scroll = [[UIScrollView alloc] init];
    scroll.translatesAutoresizingMaskIntoConstraints = NO;
    scroll.alwaysBounceVertical = YES;
    scroll.keyboardDismissMode = UIScrollViewKeyboardDismissModeOnDrag;
    [self.view addSubview:scroll];

    UIStackView *col = [[UIStackView alloc] init];
    col.axis = UILayoutConstraintAxisVertical;
    col.spacing = 12;
    col.translatesAutoresizingMaskIntoConstraints = NO;
    [scroll addSubview:col];

    self.synPanel = [self aweca_buildSyn];
    self.locPanel = [self aweca_buildLoc];
    self.locPanel.hidden = YES;
    [col addArrangedSubview:self.synPanel];
    [col addArrangedSubview:self.locPanel];
    [col addArrangedSubview:[self aweca_buildSocial]];

    UILayoutGuide *g = self.view.safeAreaLayoutGuide;
    NSLayoutConstraint *titleFromSafe = [titleLab.topAnchor constraintEqualToAnchor:g.topAnchor constant:titlePad];
    titleFromSafe.priority = UILayoutPriorityDefaultHigh;
    [NSLayoutConstraint activateConstraints:@[
        titleFromSafe,
        [titleLab.topAnchor constraintGreaterThanOrEqualToAnchor:self.view.topAnchor constant:28],
        [titleLab.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor constant:16],
        [titleLab.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor constant:-16],
        [seg.topAnchor constraintEqualToAnchor:titleLab.bottomAnchor constant:titlePad],
        [seg.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor constant:16],
        [seg.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor constant:-16],
        [scroll.topAnchor constraintEqualToAnchor:seg.bottomAnchor constant:12],
        [scroll.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],
        [scroll.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor],
        [scroll.bottomAnchor constraintEqualToAnchor:self.view.bottomAnchor],
        [col.topAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.topAnchor],
        [col.leadingAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.leadingAnchor constant:16],
        [col.trailingAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.trailingAnchor constant:-16],
        [col.bottomAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.bottomAnchor constant:-24],
        [col.widthAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.widthAnchor constant:-32],
    ]];
}

- (UIView *)aweca_buildSyn {
    UIStackView *col = [[UIStackView alloc] init];
    col.axis = UILayoutConstraintAxisVertical;
    col.spacing = 12;
    col.translatesAutoresizingMaskIntoConstraints = NO;

    UIView *card = [self aweca_card];
    UIStackView *inner = [[UIStackView alloc] init];
    inner.axis = UILayoutConstraintAxisVertical;
    inner.spacing = 0;
    inner.translatesAutoresizingMaskIntoConstraints = NO;
    [card addSubview:inner];
    [NSLayoutConstraint activateConstraints:@[
        [inner.topAnchor constraintEqualToAnchor:card.topAnchor constant:6],
        [inner.bottomAnchor constraintEqualToAnchor:card.bottomAnchor constant:-10],
        [inner.leadingAnchor constraintEqualToAnchor:card.leadingAnchor],
        [inner.trailingAnchor constraintEqualToAnchor:card.trailingAnchor],
    ]];

    [inner addArrangedSubview:[self aweca_buildHero]];
    self.speedSlider = [self aweca_makeSliderMin:0.5 max:2 val:1 tag:9101];
    self.volSlider = [self aweca_makeSliderMin:0.5 max:2 val:1 tag:9102];
    self.pitchSlider = [self aweca_makeSliderMin:0 max:2 val:1 tag:9103];
    self.silSlider = [self aweca_makeSliderMin:0 max:3000 val:0 tag:9104];
    UIView *speedRow = [self aweca_sliderBlock:@"语速" slider:self.speedSlider valPtr:&_speedVal];
    UIView *volRow = [self aweca_sliderBlock:@"音量" slider:self.volSlider valPtr:&_volVal];
    UIView *pitchRow = [self aweca_sliderBlock:@"音调" slider:self.pitchSlider valPtr:&_pitchVal];
    UIView *silRow = [self aweca_sliderBlock:@"句尾静音" slider:self.silSlider valPtr:&_silVal];
    [inner addArrangedSubview:speedRow];
    [inner addArrangedSubview:volRow];
    [inner addArrangedSubview:pitchRow];
    [inner addArrangedSubview:silRow];
    [inner addArrangedSubview:[self aweca_buildTone]];
    [inner addArrangedSubview:[self aweca_buildDialect]];
    [col addArrangedSubview:card];

    UIView *en = [self aweca_card];
    UIStackView *enRow = [[UIStackView alloc] init];
    enRow.axis = UILayoutConstraintAxisVertical;
    enRow.spacing = 4;
    enRow.translatesAutoresizingMaskIntoConstraints = NO;
    [en addSubview:enRow];
    UIView *swRow = [[UIView alloc] init];
    swRow.translatesAutoresizingMaskIntoConstraints = NO;
    UILabel *enLab = [self aweca_label:@"录音转音色" size:15 color:[UIColor labelColor]];
    UISwitch *sw = [[UISwitch alloc] init];
    sw.translatesAutoresizingMaskIntoConstraints = NO;
    [sw addTarget:self action:@selector(aweca_enhanceSwitchChanged:) forControlEvents:UIControlEventValueChanged];
    self.enhanceSwitch = sw;
    [swRow addSubview:enLab];
    [swRow addSubview:sw];
    [NSLayoutConstraint activateConstraints:@[
        [swRow.heightAnchor constraintEqualToConstant:48],
        [enLab.leadingAnchor constraintEqualToAnchor:swRow.leadingAnchor],
        [enLab.centerYAnchor constraintEqualToAnchor:swRow.centerYAnchor],
        [sw.trailingAnchor constraintEqualToAnchor:swRow.trailingAnchor],
        [sw.centerYAnchor constraintEqualToAnchor:swRow.centerYAnchor],
    ]];
    UILabel *hint = [self aweca_label:@"失败则保留原声" size:12 color:[UIColor tertiaryLabelColor]];
    [enRow addArrangedSubview:swRow];
    [enRow addArrangedSubview:hint];
    [NSLayoutConstraint activateConstraints:@[
        [enRow.topAnchor constraintEqualToAnchor:en.topAnchor constant:4],
        [enRow.bottomAnchor constraintEqualToAnchor:en.bottomAnchor constant:-12],
        [enRow.leadingAnchor constraintEqualToAnchor:en.leadingAnchor constant:16],
        [enRow.trailingAnchor constraintEqualToAnchor:en.trailingAnchor constant:-16],
    ]];
    [col addArrangedSubview:en];

    UIButton *cta = [UIButton buttonWithType:UIButtonTypeSystem];
    [cta setTitle:@"输入文字合成" forState:UIControlStateNormal];
    cta.titleLabel.font = [UIFont systemFontOfSize:16 weight:UIFontWeightSemibold];
    [cta setTitleColor:[UIColor systemBackgroundColor] forState:UIControlStateNormal];
    cta.backgroundColor = [UIColor labelColor];
    cta.tag = kAWECAInvertBtnTag;
    cta.layer.cornerRadius = 14;
    cta.translatesAutoresizingMaskIntoConstraints = NO;
    [cta.heightAnchor constraintEqualToConstant:48].active = YES;
    [cta addTarget:self action:@selector(aweca_pushCompose) forControlEvents:UIControlEventTouchUpInside];
    self.composeBtn = cta;
    [col addArrangedSubview:cta];
    return col;
